import numpy as np
from collections import Counter

class SymmetricMemeticClustering:
    def __init__(self, budget, dim, seed=None):
        self.budget = budget
        self.dim = dim
        self.rng = np.random.default_rng(seed)
        self.max_local_iter = 100
        self.crossover_rate = 0.8
        self.mutation_rate = 0.1
        self.population_size = 20
        self.diversity_threshold = 0.3
        self.elite_fraction = 0.2
        self.progressive_refinement = True

    def evaluate_solution(self, x, attach_logger=None):
        """Validates input, evaluates using IOH problem, and resets state."""
        if not isinstance(x, (list, np.ndarray)):
            raise ValueError("Input must be a numeric vector.")
        if len(x) != self.dim:
            raise ValueError(f"Input vector length {len(x)} does not match problem dimension {self.dim}.")

        try:
            problem = self._make_problem_for_run()
            objective = float(problem(x))
            if hasattr(problem, 'reset'):
                problem.reset()
            return objective
        except Exception as e:
            if hasattr(problem, 'reset'):
                problem.reset()
            raise e

    def _make_problem_for_run(self):
        # Placeholder for actual IOH problem creation
        class MockProblem:
            def __init__(self):
                self.state = type('State', (), {'evaluations': 0})()
                self.bounds = type('Bounds', (), {'lb': [0]*self.dim, 'ub': [1]*self.dim})()
                self.optimum = type('Optimum', (), {'y': 0})()

            def __call__(self, x):
