                # Simple mock clustering objective (e.g., sum of squared distances to cluster centers)
                return sum((xi - 0.5)**2 for xi in x)

            def reset(self):
                self.state.evaluations = 0

        return MockProblem()

    def local_search(self, x, func):
        """Perform local search around solution x with dynamic neighborhood."""
        best_x = x.copy()
        best_f = func(x)
        improved = True
        max_iter = self.max_local_iter

        while improved and func.state.evaluations < max_iter:
            improved = False
            # Try all neighbors in dynamic neighborhood
            for i in range(len(x)):
                neighbor = x.copy()
                neighbor[i] = 1 - neighbor[i]
                f = func(neighbor)
                if f < best_f:
                    best_f = f
                    best_x = neighbor
                    improved = True
                    break

        return best_x, best_f

    def symmetric_crossover(self, parent1, parent2):
        """Perform crossover that respects symmetry in clustering."""
        if self.rng.random() > self.crossover_rate:
            return parent1.copy(), parent2.copy()

        # Uniform crossover with symmetry correction
        child1 = parent1.copy()
        child2 = parent2.copy()

        # Apply crossover
        for i in range(len(parent1)):
            if self.rng.random() < 0.5:
                child1[i], child2[i] = child2[i], child1[i]

        # Apply symmetry correction: if many elements are 1s, flip all
        if sum(child1) > len(child1) / 2:
            child1 = [1 - v for v in child1]
        if sum(child2) > len(child2) / 2:
            child2 = [1 - v for v in child2]

        return child1, child2

    def symmetric_mutation(self, x):
        """Apply mutation that respects symmetry in clustering."""
        mutated = x.copy()
        # Apply mutation with probability
        for i in range(len(x)):
            if self.rng.random() < self.mutation_rate:
                mutated[i] = 1 - mutated[i]

        # Apply symmetry correction: if many elements are 1s, flip all
        if sum(mutated) > len(mutated) / 2:
            mutated = [1 - v for v in mutated]

        return mutated

    def adaptive_neighborhood_tuning(self, func, x, current_evals):
        """Adaptively tune neighborhood size based on evaluation progress."""
        # Simple adaptive strategy: reduce neighborhood size as evaluations increase
        max_neighborhood = max(1, int(self.dim * (1 - current_evals / self.budget)))
        return max_neighborhood

    def elite_guided_mutation(self, x, elite_individuals):
        """Apply mutation guided by elite individuals to preserve good characteristics."""
        mutated = x.copy()

        # If there are elite individuals, use their characteristics to guide mutation
        if elite_individuals:
            # Calculate frequency of each bit position across elites
            bit_frequencies = [0] * len(x)
            for elite in elite_individuals:
                for i in range(len(elite)):
                    bit_frequencies[i] += elite[i]

            # Mutate based on frequency - if majority is 1, prefer 0 and vice versa
            for i in range(len(mutated)):
                if self.rng.random() < self.mutation_rate:
                    if bit_frequencies[i] > len(elite_individuals) / 2:
                        mutated[i] = 1 - mutated[i]  # Flip if majority is 1
                    else:
                        mutated[i] = 1 - mutated[i]  # Flip if majority is 0

        return mutated

    def progressive_refinement(self, func, population):
        """Apply progressive refinement to improve convergence."""
        if not self.progressive_refinement:
            return population

        # Sort population by fitness
        fitness = [func(x) for x in population]
        sorted_indices = np.argsort(fitness)

        # Refine top individuals progressively
        refined_population = []
        for i, idx in enumerate(sorted_indices):
            if i < len(population) // 2:  # Refine top half
                x = population[idx]
                x_refined, _ = self.local_search(x, func)
                refined_population.append(x_refined)
            else:
                refined_population.append(population[idx])

        return refined_population

